/**
 * Defines the structured JSON schema and item types for the AI Notes Generation Engine.
 * 
 * Every piece of educational content generated by the AI is represented as a typed element,
 * completely separating educational content generation from React document rendering.
 */

export const NOTE_CONTENT_TYPES = {
  CHAPTER_TITLE: 'chapter_title',
  SECTION_HEADING: 'section_heading',
  SUBSECTION_HEADING: 'subsection_heading',
  PARAGRAPH: 'paragraph',
  DEFINITION: 'definition',
  IMPORTANT_POINT: 'important_point',
  FORMULA: 'formula',
  DERIVATION: 'derivation',
  BULLET_LIST: 'bullet_list',
  NUMBERED_LIST: 'numbered_list',
  COMPARISON_TABLE: 'comparison_table',
  EXAMPLE: 'example',
  SOLVED_NUMERICAL: 'solved_numerical',
  DIAGRAM: 'diagram',
  FLOWCHART: 'flowchart',
  ALGORITHM: 'algorithm',
  ADVANTAGES_DISADVANTAGES: 'advantages_disadvantages',
  APPLICATION: 'application',
  EXAM_QUESTION: 'exam_question',
  WARNING: 'warning',
  KEY_TAKEAWAY: 'key_takeaway',
  SUMMARY: 'summary',
  REVISION_CHECKLIST: 'revision_checklist'
};

export const DETAIL_LEVELS = {
  QUICK: 'quick',
  STANDARD: 'standard',
  DETAILED: 'detailed',
  EXHAUSTIVE: 'exhaustive'
};

export const NOTE_THEMES = {
  HANDWRITTEN: 'handwritten',
  ACADEMIC: 'academic',
  EXAM: 'exam'
};

export const SCHEMA_DOCS = `
Output MUST be a JSON object with:
{
  "chapter_title": string,
  "subject": string,
  "estimated_reading_time": string,
  "coverage_checklist": [string],
  "sections": [
    {
      "id": string,
      "title": string,
      "importance": "HIGH" | "MEDIUM" | "ADDITIONAL",
      "blocks": [
        // array of typed content elements (paragraph, definition, formula, derivation, comparison_table, solved_numerical, diagram, exam_question, etc.)
      ]
    }
  ],
  "chapter_summary": string,
  "formula_sheet": [
    { "title": string, "latex": string, "symbols": [{ "symbol": string, "meaning": string }] }
  ],
  "revision_checklist": [string]
}
`;
